diff --git a/core/forks/compare.js b/core/forks/compare.js
index a5e09b3..8fedc27 100644
--- a/core/forks/compare.js
+++ b/core/forks/compare.js
@@ -3,6 +3,20 @@
 const { assertValidFork, EXECUTOR_FORK_SCHEMA_VERSION } = require('./contracts');
 const { missionControlExecutorState } = require('./executor-profiles');

+/**
+ * Reason codes that mean the stored receipt contradicts the branch record it
+ * claims to cover -- a receipt left by an interrupted attempt, or one bound to
+ * another attempt, branch, or issuer. These disqualify a branch under every
+ * schema: the branch record's own `receipt_verified` flag is written before the
+ * outcome is durable and can never override fresh verification.
+ */
+const RECEIPT_CONTRADICTIONS = Object.freeze([
+  'EXECUTION_RECEIPT_DIGEST_MISMATCH',
+  'EXECUTION_RECEIPT_BINDING_MISMATCH',
+  'EXECUTION_RECEIPT_BRANCH_MISMATCH',
+  'FORK_RECEIPT_BINDING_MISMATCH',
+]);
+
 /**
  * `verification` is the result of freshly verifying the stored fork receipt
  * wrapper and execution receipt for this branch. Schema 2 fails closed when
@@ -22,6 +36,8 @@ function comparableBranch(branch, fork, verification) {
   if (fork.schema_version === EXECUTOR_FORK_SCHEMA_VERSION
     && (!verification || verification.status !== 'verified')) {
     reasons.push('fork-receipt-unverified');
+  } else if (verification && RECEIPT_CONTRADICTIONS.includes(verification.reason_code)) {
+    reasons.push('receipt-mismatched');
   }
   return { comparable: reasons.length === 0, reasons };
 }
