diff --git a/scripts/test-operation-fork.js b/scripts/test-operation-fork.js
index 9c367c7..f172df8 100644
--- a/scripts/test-operation-fork.js
+++ b/scripts/test-operation-fork.js
@@ -119,6 +119,35 @@ assert.equal(resumed.fork.branches.find((branch) => branch.runtime === 'claude')
 assert.equal(resumed.fork.branches.find((branch) => branch.runtime === 'claude').failure_code, 'RUNTIME_EFFECT_AMBIGUOUS');
 assert.deepEqual(calls, ['codex'], 'ambiguous Claude effect must not run again');

+// A resumed fork must re-derive receipt trust from disk. Swap in the sibling
+// branch's receipt: correctly signed, but bound to another attempt. Staleness is
+// a digest comparison, so it must be caught without consulting the branch
+// record's own receipt_verified flag and without any signer anchor.
+const receiptsDir = path.join(project, '.planning', 'operation-forks', 'fork-auth-race', 'receipts');
+fs.copyFileSync(path.join(receiptsDir, 'branch-codex.json'), path.join(receiptsDir, 'branch-claude.json'));
+const stale = forks.loadFork(project, 'fork-auth-race');
+const staleBranch = stale.branches.find((branch) => branch.branch_id === 'branch-claude');
+assert.equal(forks.verifyBranchEvidence(project, stale, staleBranch).verification.reason_code,
+  'EXECUTION_RECEIPT_DIGEST_MISMATCH');
+const staleComparison = forks.compareFork(stale, { evidence: forks.forkEvidence(project, stale) });
+const staleEntry = staleComparison.branches.find((branch) => branch.branch_id === 'branch-claude');
+assert.equal(staleEntry.comparable, false, 'a mismatched receipt must not stay comparable');
+assert(staleEntry.reasons.includes('receipt-mismatched'), staleEntry.reasons.join(','));
+assert.throws(() => forks.applySelection({ projectRoot: project, forkId: 'fork-auth-race',
+  branchId: 'branch-claude', expectedRevision: stale.revision, actorId: 'actor-operator',
+  idempotencyKey: 'select-stale-001', reason: '' }), { code: 'FORK_BRANCH_INCOMPARABLE' });
+// Landing is the irreversible effect, so it must refuse the same contradiction even
+// after a branch was legitimately selected while its receipt still matched.
+const landingFork = forks.selectBranch(stale, { branchId: 'branch-codex', expectedRevision: stale.revision,
+  actorId: 'actor-operator', idempotencyKey: 'select-codex-001', reason: '',
+  receiptVerification: { status: 'verified', reason_code: 'FORK_RECEIPT_VERIFIED' },
+  selectedAt: '2026-07-13T14:00:00.000Z' });
+assert.throws(() => forks.prepareLanding(landingFork, { expectedRevision: landingFork.revision,
+  targetRevision: baseRevision, confirmation: forks.landingConfirmation(landingFork, baseRevision),
+  idempotencyKey: 'land-stale-001', confirmedAt: '2026-07-13T14:00:01.000Z',
+  receiptVerification: { status: 'invalid', reason_code: 'EXECUTION_RECEIPT_DIGEST_MISMATCH' },
+}), { code: 'FORK_BRANCH_INCOMPARABLE' });
+
 for (const branch of [...result.fork.branches, ...recovery.branches]) {
   const target = provider.resolve(project, worktrees, branch.run_id.includes('recovery') ? 'fork-recovery' : 'fork-auth-race', branch.branch_id);
   if (fs.existsSync(target)) git(project, ['worktree', 'remove', '--force', target]);
